@import url("s://fonts.googleapis.com/css2?family=Inter:wght@400;500&display=swap");

.cir-search {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: 320px;
  height: 48px;
  padding: 0 8px 0 18px;
  background: var(--color-cloud, #ffffff);
  border: 1px solid var(--color-edge, #e3e8ee);
  border-radius: 999px;
  box-shadow:
    0 1px 1px rgba(14, 17, 22, 0.03),
    0 18px 36px -22px rgba(14, 17, 22, 0.18);
  font-family:
    "Inter",
    system-ui,
    -apple-system,
    sans-serif;
  transition:
    border-color 220ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.cir-search__icon {
  width: 16px;
  height: 16px;
  color: var(--color-mist, #5b6472);
  flex-shrink: 0;
}

.cir-search__field {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  font: inherit;
  font-size: 14px;
  color: var(--color-ink, #0e1116);
}

.cir-search__field::placeholder {
  color: #8a93a3;
}

.cir-search__kbd {
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 0 10px;
  background: #f3f6fa;
  border: 1px solid #eef2f6;
  border-radius: 999px;
  font-family: "Inter", system-ui, sans-serif;
  font-size: 11px;
  font-weight: 500;
  color: var(--color-mist, #5b6472);
  letter-spacing: 0.02em;
}

.cir-search:focus-within {
  border-color: var(--color-signal, #2e7def);
  box-shadow:
    0 0 0 3px rgba(46, 125, 239, 0.22),
    0 18px 36px -22px rgba(14, 17, 22, 0.2);
}

